  name: 'stroke-width',
  size: 24,
  node: [
    ['path', { d: 'M3.25 3h17.5', key: 'r8pwzv' }],
    ['rect', { x: '3', y: '7', width: '18', height: '4', rx: '1', key: '1hberx' }],
    ['rect', { x: '3', y: '15', width: '18', height: '6', rx: '1', key: '1epx01' }],
  ],
};

/**
 * @deprecated Access `__iconData` instead.
 */
export const __iconNode: LucideIconNode[] = __iconData.node;

/**
 * @component @name StrokeWidth
 * @description Lucide SVG icon component, renders SVG Element with children.
 *
 * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/stroke-width
 * @see https://lucide.dev/guide/packages/lucide-react - Documentation
 *
 * @param {Object} props - Lucide icons props and any valid SVG attribute
 * @returns {JSX.Element} JSX Element
 *
 */
const StrokeWidth = createLucideIcon(__iconData);

export default StrokeWidth;
